DEFINE iSqlErr 		INTEGER;
DEFINE cCodRetSp 	CHAR(5);	
DEFINE iCodRetSp INTEGER;

LET cCodRet     = '00000';
LET iSqlErr     =  0;
LET cCodRetSp 	= '';	
LET iCodRetSp   =  0;

BEGIN

	ON EXCEPTION SET iSqlErr
		LET cCodRet = iSqlErr;
		RETURN cCodRet;
	END EXCEPTION;

	--SET DEBUG FILE TO '/tmp/mfinis/sp_ope_altabajactaspei.out';
	--TRACE ON;

	IF pUsuario = '' OR pNoCuentaClabe=''  OR pOperacion='' THEN
		LET cCodRet = '00003';
		RETURN cCodRet;
	END IF;

	EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
	IF cCodRet <> '00000' THEN
		RETURN cCodRet;
	END IF;

	SET ISOLATION TO DIRTY READ;            
    SET LOCK MODE TO WAIT 3;

	IF(pOperacion='1')	THEN
		EXECUTE PROCEDURE bdispei:"informix".sp_altactaspei(pNoCuentaClabe,pUsuario) INTO cCodRetSp;

		LET iCodRetSp = cCodRetSp::INTEGER;

		IF iCodRetSp < 0 THEN
			RAISE EXCEPTION iCodRetSp, 0, "ERROR EN LA EJECUCION DEL SP bdispei:'informix'.sp_altactaspei";
		ELIF iCodRetSp = 101 THEN
			LET cCodRet = '00987'; --  CUENTA INVALIDA 
		ELIF iCodRetSp = 102 THEN
			LET cCodRet = '00988'; -- 	EL NÚMERO DE CUENTA CLABE YA SE ENCUENTRA BLOQUEADO 
		END IF;

		RETURN cCodRet;

	ELSE
		EXECUTE PROCEDURE bdispei:"informix".sp_bajactaspei(pNoCuentaClabe,pUsuario) INTO cCodRetSp;

		LET iCodRetSp = cCodRetSp::INTEGER;

		IF iCodRetSp < 0 THEN
			RAISE EXCEPTION iCodRetSp, 0, "ERROR EN LA EJECUCION DEL SP bdispei:'informix'.sp_bajactaspei";
		ELIF iCodRetSp = 102 THEN
			LET cCodRet = '00988'; -- EXISTE CUENTA CON EDO CANCELADO 
		ELIF iCodRetSp = 103 THEN
			LET cCodRet = '00989'; -- LA CUENTA CLABE NO EXISTE 
		END IF;

		RETURN cCodRet;

	END IF;

	RETURN cCodRet;

END;


END PROCEDURE
