			END IF;

			LET iRecuperacion = iRecuperacion + 1;				
			RETURN cCodRet, TRIM(cIdBanco),TRIM(UPPER(cNomBanco)) WITH RESUME;	
		END FOREACH;

		IF iRecuperacion = 0 THEN
			LET cCodRet = '00017';
